INSERT INTO "main"."iot_protocol" ("id", "name", "description", "form_json", "sort", "status", "created_at", "updated_at") VALUES ('c1bbaa92-be7e-4fcf-8cf1-ce5605720028', 'DLT645.Serial', '', '{"rule":[{"type":"select","field":"protocolVersion","title":"协议版本","info":"2007 版数据标识为 4 字节，1997 版为 2 字节；选错表现为设备无应答（超时）","effect":{"fetch":""},"$required":true,"options":[{"label":"DL/T 645-2007","value":"2007"},{"label":"DL/T 645-1997","value":"1997"}],"display":true,"hidden":false},{"type":"input","field":"meterAddress","title":"表号","info":"1~12 位十进制表号，不足左补零，如 000000000001","effect":{"fetch":""},"$required":true,"display":true,"hidden":false},{"type":"input","field":"comPort","title":"设备端口","info":"如 COM1、/dev/ttyUSB0","effect":{"fetch":""},"$required":true,"display":true,"hidden":false},{"type":"select","field":"baudRate","title":"波特率","info":"645 电表出厂多为 2400","effect":{"fetch":""},"$required":false,"options":[{"label":"600","value":"600"},{"label":"1200","value":"1200"},{"label":"2400","value":"2400"},{"label":"4800","value":"4800"},{"label":"9600","value":"9600"},{"label":"19200","value":"19200"},{"label":"38400","value":"38400"},{"label":"57600","value":"57600"},{"label":"115200","value":"115200"}],"display":true,"hidden":false},{"type":"select","field":"dataBits","title":"数据位","info":"","effect":{"fetch":""},"$required":false,"options":[{"label":"8","value":"8"},{"label":"7","value":"7"},{"label":"6","value":"6"},{"label":"5","value":"5"}],"display":true,"hidden":false},{"type":"select","field":"stopBits","title":"停止位","info":"","effect":{"fetch":""},"$required":false,"options":[{"label":"1","value":"1"},{"label":"2","value":"2"}],"display":true,"hidden":false},{"type":"select","field":"parity","title":"校验位","info":"645 电表几乎全为偶校验","effect":{"fetch":""},"$required":false,"options":[{"label":"偶校验","value":"E"},{"label":"无校验","value":"N"},{"label":"奇校验","value":"O"}],"display":true,"hidden":false},{"type":"inputNumber","field":"timeoutMs","title":"单帧超时(ms)","info":"默认 3000；波特率低时过小会截断应答帧，驱动按波特率设有下限","effect":{"fetch":""},"$required":false,"display":true,"hidden":false},{"type":"inputNumber","field":"interFrameDelayMs","title":"收发间延时(ms)","info":"默认 30；RS-485 收发器换向与电表处理时间","effect":{"fetch":""},"$required":false,"display":true,"hidden":false},{"type":"inputNumber","field":"preambleBytes","title":"前导唤醒字节数","info":"0~4，串口默认 4（FE FE FE FE）","effect":{"fetch":""},"$required":false,"display":true,"hidden":false},{"type":"inputNumber","field":"maxDIsPerRead","title":"单请求数据标识数","info":"默认 1（逐个读）；大于 1 时遇异常应答会自动降级为逐个读取","effect":{"fetch":""},"$required":false,"display":true,"hidden":false},{"type":"inputNumber","field":"maxFollowUpFrames","title":"后续帧上限","info":"默认 2，仅 2007 版生效；防止异常表返回后续帧标志时挂死轮询","effect":{"fetch":""},"$required":false,"display":true,"hidden":false},{"type":"select","field":"checkChecksum","title":"校验码校验","info":"默认校验；少数表的校验和计算不规范时可关闭，改为仅校验帧结构","effect":{"fetch":""},"$required":false,"options":[{"label":"校验","value":"true"},{"label":"不校验","value":"false"}],"display":true,"hidden":false}],"options":{"form":{"inline":false,"hideRequiredAsterisk":false,"labelPosition":"right","size":"default","labelWidth":"125px"},"resetBtn":{"show":false,"innerText":"重置"},"submitBtn":{"show":false,"innerText":"提交"}}}', 1, 1, '2026-09-20 10:00:00', '2026-09-20 10:00:00');
